type Shape =
  | { kind: 'circle'; r: number }
  | { kind: 'square'; s: number }
  | { kind: 'triangle'; b: number; h: number };

function assertNever(x: never): never {
  throw new Error('Unhandled: ' + JSON.stringify(x));
}

function area(shape: Shape): number {
  switch (shape.kind) {
    case 'circle': return Math.PI * shape.r ** 2;
    case 'square': return shape.s ** 2;
    case 'triangle': return 0.5 * shape.b * shape.h;
    default: return assertNever(shape);
  }
}

console.log(area({ kind: 'triangle', b: 4, h: 2 }));

interface Config { port: number; host: string; }

function fail(msg: string): never {
  throw new Error(msg);
}

function parseConfig(input: unknown): Config {
  if (typeof input !== 'object' || input === null) {
    return fail('Config must be an object');
  }
  const obj = input as Record<string, unknown>;
  if (typeof obj.port !== 'number') return fail('port must be a number');
  if (typeof obj.host !== 'string') return fail('host must be a string');
  return { port: obj.port, host: obj.host };
}

console.log(parseConfig({ port: 8080, host: 'localhost' }));
try { parseConfig({ port: '80' }); } catch (e) { console.log((e as Error).message); }
